import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;
import java.io.IOException;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author prakhar17252
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int a = in.nextInt();
            int b = in.nextInt();
            int l = in.nextInt();
            int r = in.nextInt();

            out.println(fun(a, b, l, r));
        }

        static int fun(int a, int b, int l, int r) {
            if ((r - l + 1) > 2 * (a + b))
                if (a <= b)
                    return a + 1;
                else
                    return (2 * a - b);

            int[] flag = new int[3 * (a + b) + 1];

            int temp = 0;
            for (int i = 1; i <= a; i++) {
                flag[i] = i;
                temp = i;
            }

            for (int i = a + 1; i <= a + b; i++) {
                flag[i] = temp;
            }

            for (int i = a + b + 1; i <= a + b + a; i++) {
                int tc = 1;
                while (in(flag, tc, a + b - a + 1, i - 1))
                    tc++;
                flag[i] = tc;
                temp = flag[i];
            }
            for (int i = a + b + a + 1; i <= a + b + a + b; i++) {
                flag[i] = temp;
            }
            for (int i = 2 * (a + b) + 1; i <= 3 * (a + b); i++) {
                flag[i] = flag[i - (a + b)];
            }

            int[] flagc = new int[25];
            int templ = l % (a + b);
            if (templ == 0) templ += a + b;
            int tempr = r - l + templ;
            if (tempr < templ) tempr += a + b;
            for (int i = templ; i <= tempr; i++) {
                flagc[flag[i]] = 1;
            }

            int res = 0;
            for (int i = 1; i <= 24; i++)
                res += flagc[i];

            return res;

        }

        static boolean in(int[] a, int b, int l, int r) {
            for (int i = l; i <= r; i++) {
                if (a[i] == b)
                    return true;
            }
            return false;
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}


